#include "../Source/EARTHtotaled/ETTerrainMath.h"
#include <cassert>
#include <cstdio>

int main()
{
    int Samples=0;
    double Low=10000,High=-10000;
    for(int CX=-25;CX<=25;++CX) for(int CY=-25;CY<=25;++CY)
    {
        // The same border point generated by each adjacent chunk must match exactly.
        const double AX=CX*32000.0+40*800.0, BX=(CX+1)*32000.0;
        const double Y=CY*32000.0+17*800.0;
        assert(ETMath::Height(AX,Y,84371)==ETMath::Height(BX,Y,84371));
        const double H=ETMath::Height(AX,Y,84371);
        assert(std::isfinite(H)); assert(std::abs(H)<3136);
        assert(H==ETMath::Height(AX,Y,84371));
        assert(std::abs(ETMath::Height(AX-.01,Y,84371)-ETMath::Height(AX+.01,Y,84371))<.1);
        const double Ridge=ETMath::Relief(AX,Y,84371);
        assert(Ridge==ETMath::Relief(BX,Y,84371));
        assert(std::abs(ETMath::Relief(AX-.01,Y,84371)-ETMath::Relief(AX+.01,Y,84371))<.1);
        assert(Ridge!=ETMath::Relief(AX,Y,84372));
        Low=std::fmin(Low,H+Ridge); High=std::fmax(High,H+Ridge);
        ++Samples;
    }
    assert(ETMath::Height(1200000,-1900000,84371)!=ETMath::Height(1200000,-1900000,84372));
    assert(ETMath::Height(9000000,7000000,84371)!=ETMath::Height(9000100,7000000,84371));
    assert(High-Low>6000);
    std::printf("Seeded hill and valley sample spans %.1f metres.\n",(High-Low)/100.);
    std::printf("%d shared terrain samples passed: negative coordinates, chunk seams, determinism, seed changes and distant terrain.\n",Samples);
}
